window.RP_SESSION={"id":"S-9890746b8165","messages":[{"id":"RP-II-0162990","time":"2026-08-23T06:18:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 이~상하네... \"\n\n갸웃.\n\n\" 요~상하단 말이쥐... \"\n\n기우뚱.","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0162991","time":"2026-08-23T06:19:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 하- 거참... \"\n\n숀입니다.\n\n그는 매일 아침 일어나 수레에 담긴 고장난 장비를 브랜이 고쳐둘 수 있게 대장간으로 옮겨두고 있다는 것은 이제 우리 모두 알고 있습니다.\n\n그런 그는 이른 아침마다 정해진 시간에 정해진 동선으로 걷죠.","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0162992","time":"2026-08-23T06:21:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"그런데 이상한 점 하날 눈치챕니다.\n\n\" 사이먼 걔. 아침마다 애들 글공부 시켰던 것 같은데... \"\n\n사이먼요.\n\n분명 요 며칠 아침마다 글을 못 읽는 길드원들을 위해 글공부시켰던 것 같은데...\n\n\" 공부기간 다 끝났나? \"\n\n도통 사이먼이 애들 가르키는 소리가 어느날 뚝. 끊긴 겁니다.","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0162993","time":"2026-08-23T06:23:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 뭐... \"\n\n숀은 잠시 멈추어 길드 건물을 바라본 뒤...\n\n\" 알아서 하겠쥐. 걘 지 일은 알아서 잘하니까. \" \n\n찜찜한 기분과 함께 수레를 끌며 대장간으로 향했습니다.","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0162994","time":"2026-08-23T06:23:00+09:00","room":"RP II","name":"숀","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-5c88d36f51cd"]},{"id":"RP-II-0162995","time":"2026-08-23T06:23:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
